package refaccio;

public class CalculadoraEnviament {
    // TÈCNICA 1: Extract Constant (eliminació de números màgics)
    private static final double LLINDAR_PES_ALT = 10.0;
    private static final double TARIFA_NACIONAL = 2.5;
    private static final double RECARREC_NACIONAL = 5.0;
    private static final double URGENCIA_NACIONAL = 0.20;
    private static final double TARIFA_EUROPA = 5.0;
    private static final double RECARREC_EUROPA = 12.0;
    private static final double URGENCIA_EUROPA = 0.30;
    private static final double TARIFA_INTERNACIONAL = 10.0;
    private static final double RECARREC_INTERNACIONAL = 25.0;
    private static final double URGENCIA_INTERNACIONAL = 0.40;

    public static double calcularCostEnviament(String destinacio, double pes, boolean esUrgent) {
        switch (destinacio) {
            case "NACIONAL":
                return calcularPerZona("Nacional", pes, esUrgent, TARIFA_NACIONAL, RECARREC_NACIONAL, URGENCIA_NACIONAL);
            case "EUROPA":
                return calcularPerZona("Europa", pes, esUrgent, TARIFA_EUROPA, RECARREC_EUROPA, URGENCIA_EUROPA);
            case "INTERNACIONAL":
                return calcularPerZona("Internacional", pes, esUrgent, TARIFA_INTERNACIONAL, RECARREC_INTERNACIONAL, URGENCIA_INTERNACIONAL);
            default:
                System.out.println("Error: Destinació no reconeguda.");
                return -1.0;
        }
    }

    // TÈCNICA 2: Extract Method (eliminació de codi duplicat entre zones)
    private static double calcularPerZona(String nomZona, double pes, boolean esUrgent,
            double tarifaKg, double recarrecPes, double factorUrgencia) {
        double costBase = pes * tarifaKg;
        if (pes > LLINDAR_PES_ALT) {
            costBase += recarrecPes;
        }
        double costFinal = esUrgent ? costBase + (costBase * factorUrgencia) : costBase;
        System.out.println("Enviament " + nomZona + ": " + costFinal + " € total.");
        return costFinal;
    }
}

